#include "ksTimingTablesTask.h"
#include <stdexcept>
#include <iostream>
#include <vector>
int main(){using T=ks::TimingTablesTask;using S=T::Stage;using K=T::Kind;using R=T::Read;unsigned cases=0;for(unsigned kind=0;kind<4;++kind)for(unsigned rate=0;rate<65536;++rate){T t(static_cast<K>(kind));unsigned used=0,reads=0,children=0;std::vector<uint32_t>writes;while(t.stage()!=S::Complete){if(t.child()!=T::Child::None){if(t.child()!=(children?T::Child::Multiply:T::Child::Reciprocal)||children>1)throw std::runtime_error("child order");++children;t.resumeChild();continue;}auto cost=t.nextClocks();if(t.advanceBefore(cost-1,[](R)->unsigned{throw std::runtime_error("early read");},[](unsigned,uint32_t){throw std::runtime_error("early write");}))throw std::runtime_error("early budget");used+=t.advanceBefore(cost,[&](R r){++reads;return r==R::Counter||r==R::Rate?rate:uint16_t(rate+t.index()*0x9e37);},[&](unsigned index,uint32_t value){if(index!=writes.size())throw std::runtime_error("output order");writes.push_back(value);});}std::vector<uint32_t>expected;if(kind>=2)for(unsigned i=0;i<34;++i){unsigned raw=uint16_t(rate+i*0x9e37);if(kind==2){unsigned seed=uint16_t(rate?0x3e800000u/rate:0),divisor=uint16_t(raw<<4);expected.push_back(divisor?uint32_t((uint64_t(seed)<<16)/divisor)<<1:0);}else{unsigned factor=uint32_t(0x8312u*rate<<1)>>16;expected.push_back(uint32_t(uint16_t(raw<<5))*factor);}}if(writes!=expected||used!=(kind==0?25:kind==1?47:kind==2?3349:2156)||reads!=(kind==0?1:kind==1?0:35)||children!=(kind==1?2:0)||t.remaining()||t.index()!=(kind>=2?34:0)||t.resumeChild())throw std::runtime_error("timing math/child/clocks/lifecycle");if(kind==0&&t.counter()!=rate)throw std::runtime_error("timer");++cases;}std::cout<<"PASS: "<<cases<<" pure timing-tables properties\n";}
